#pragma once

// Entry checks of stxlib::File, generated by tools/ic_declarations.py from include/stxlib/files.ic.toml; edit the
// declaration, not this file. Each predicate is one `requires` clause of the declaration, so the condition the header
// states and the check the code runs are one text (docs/ic_declarations.md in template_harness).

#include "stxlib/types.hpp"

namespace stxlib::detail::ic::files {

// 2^63 - 1
inline constexpr u64 largest_offset = 0x7fffffffffffffffULL;

// File::read_at: offset <= largest_offset; else failure limit_exceeded (too_long).
[[nodiscard]] constexpr bool admits_read_at_offset(const u64 offset) noexcept {
    const bool result = offset <= largest_offset;
    return result;
}

// File::write_all_at: offset <= largest_offset and length <= largest_offset - offset; else failure limit_exceeded
// (too_long).
[[nodiscard]] constexpr bool admits_write_at_extent(const u64 offset, const usize length) noexcept {
    const bool result = (offset <= largest_offset) && (length <= (largest_offset - offset));
    return result;
}

// File::set_size: bytes <= largest_offset; else failure limit_exceeded (too_long).
[[nodiscard]] constexpr bool admits_set_size_bytes(const u64 bytes) noexcept {
    const bool result = bytes <= largest_offset;
    return result;
}

} // namespace stxlib::detail::ic::files
